\section{Implementation}
\label{sec:implement}

For the sake of completeness, we provide a detailed derivation of the implementation of measurement, where subsections \ref{sec:low-lvl-CSS-measurement} and \ref{sec:low-lvl-non-CSS-measure} treat the special CSS and more general non-CSS case separately.
In particular, we show that measurement errors arise due to physical errors on check qubits.

\subsection{Low Level CSS Measurement}
\label{sec:low-lvl-CSS-measurement}

We adopt the convention that given a $\F_2$ space $X$, the space is always equipped with basis $\cX$. We also adopt the notation that $Q(X)$ is an (isometric) copy of $X$ with corresponding basis $\cQ(X)$.

\begin{lemma}[Low Level]
\label{lem:low-lvl-measurement}
Algorithm \ref{alg:low-lvl-measurement} is correct.
\end{lemma}

\begin{remark}[Physical $\lr$ Measurement Error]
    \label{rem:phys-meas-errs}
    Note that at the low-level implementation, the $Z$-type physical error $e_Z(X^B)$ on discarded qubits converts to a measurement error in the readout.
\end{remark}

\begin{proof}
    By Lemma \ref{lem:overcomplete-physicals}, the valid measurement condition is equivalent to
    \begin{equation}
        e_Z + s_Z \in \ker\delta +Q(X^B)^\perp
    \end{equation}
    where $s_Z(X^B) \in Q(X^B)$ is the readout and $e_Z =e_Z(X^B) \oplus e_Z(Q^A)$ where $e_Z(X^B) \in Q(X^B)$ and $e_Z(Q^A) \in Q^A$. Note that if $\ell_Z\in \ker \delta$, we have $\ell_Z(Q^A) \in \ker \delta^A$ and $\ell_Z(X^B) = \delta^B \ell_Z(Q^A)$. Hence,
    \begin{equation}
        s_Z = \delta^B \ell_Z(Q^A) + e_Z(X^B)
    \end{equation}
    Again, by Lemma \ref{lem:overcomplete-physicals}, the residual $Z$-type physical error, modulo logical, is then $e_Z(Q^A) +\ell_Z(Q^A)$, since qubits $Q(X^B)$ are discarded.
    The $X$-type residual physical errors are straightforward.
\end{proof}

\begin{lemma}[High Level Measurement]
    Algorithm \ref{alg:high-lvl-measurement} is correct.
\end{lemma}

\begin{algorithm}
\caption{\textsc{Low-Level Measurement}}
\label{alg:low-lvl-measurement}
\begin{algorithmic}[1]
    \Require State stabilized by complex with (co)differential $\partial$ ($\delta$)
    \begin{equation}
        \label{eq:low-lvl-measurement}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        {&X^B & Q(X^B)\\
         X^A &Q^A & Z^A\\};
        \path[->,font=\scriptsize]
        (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3)
        (a-2-1) edge node[above]{$\partial^A$}  (a-2-2)
        (a-2-2) edge node[above]{$\partial^A$}  (a-2-3)
        (a-1-2) edge node[right]{$\partial^B$}  (a-2-2)
        (a-1-3) edge node[right]{$g=\partial^A \partial^B$}  (a-2-3);
        \end{tikzpicture}
    \end{equation}
    (where the bottom row is also a complex $A$) with (unknown) physical $e_{\bullet}(Q^A)\in Q^A,e_{\bullet}(X^B) \in Q(X^B)$.
    \Ensure Readout
    \begin{equation}
        \delta^B \ell_Z(Q^A) +e_Z(X^B) \in X^B
    \end{equation}
    for some logical $\ell_Z(Q^A) \in \ker \delta^A$ and output state stabilized by
    \begin{itemize}
        \item $X$ Paulis in $\im \partial^A +\im \partial^B$ with physical $e_Z(Q^A)+\ell_Z(Q^A)$
        \item $Z$ Paulis in $\im \delta^A \cap (\im \partial^B)^\perp$ with physical $e_X(Q^A)$
    \end{itemize}
    \State Measure out $Q(X^B)$ in the $X$-basis with physical measurement $s\in Q(X^B) \cong X^B$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\textsc{High-Level Measurement}}
\label{alg:high-lvl-measurement}
\begin{algorithmic}[1]
    \Require State stabilized by CSS code
    \begin{equation}
        A= X^A \xrightarrow{\partial^A} Q^A \xrightarrow{\partial^A} Z^A
    \end{equation}
    with (unknown) physical $e_{\bullet}(Q^A)$.
    Circuit to perform $X$-type measurement $\partial^B:X^B \to Q^A$.
    \Ensure Valid syndrome
    \begin{equation}
        \delta^B (e_Z(Q^A) +\ell_Z(Q^A)) \in X^B
    \end{equation}
    for some logical $\ell_Z(Q^A) \in \ker \delta^A$ and output stabilized by
    \begin{itemize}
        \item $X$ Paulis in $\im \partial^A +\im \partial^B$ with physical $e_Z(Q^A)+\ell_Z(Q^A)$
        \item $Z$ Paulis in $\im \delta^A \cap (\im \partial^B)^\perp$ with physical $e_X(Q^A)$
    \end{itemize}
    \State Perform $X$-type measurement $\partial^B:X^B \to Q^A$ with valid syndrome $\in X^B$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\textsc{Low-Level with CNOTs}}
\label{alg:low-lvl-wCNOTs}
\begin{algorithmic}[1]
    \Require State stabilized by CSS code
    \begin{equation}
        A= X^A \xrightarrow{\partial^A} Q^A \xrightarrow{\partial^A} Z^A
    \end{equation}
    with (unknown) physical $e_{\bullet}(Q^A)$.


    \Ensure Measure $X$-Paulis in $\partial^B:X^B \to Q^A$ with readout
    \begin{equation}
        \delta^B (e_Z(Q^A) +\ell_Z(Q^A)) +e_Z(X^B) \in X^B
    \end{equation}
     where $e_Z(X^B)$ is an unknown initialization error, and $\ell_Z(Q^A) \in \ker \delta^A$. The output state is stabilized by
    \begin{itemize}
        \item $X$ Paulis in $\im \partial^A +\im \partial^B$ with physical $e_Z(Q^A)+\ell_Z(Q^A)$
        \item $Z$ Paulis in $\im \delta^A \cap (\im \partial^B)^\perp$ with physical $e_X(Q^A)$
    \end{itemize}
    \State Initialize check qubits $Q(X^B)$ transversally in $X$-basis with (unknown) physicals $e_Z(X^B)$
    \Comment{Example \ref{ex:initialization}}
    \State Apply CNOT circuits from $Q(X^B)\to Q^A$ based on $\partial^B$
    \State Measure out $Q(X^B)$ in the $X$-basis with physical $\in Q(X^B) \cong X^B$
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Relation]
    Algorithm \ref{alg:low-lvl-wCNOTs} is correct.
\end{lemma}
\begin{proof}
    After initialization (line 1), the state is stabilized by
    \begin{equation}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        {&X^B & Q(X^B)\\
         X^A &Q^A & Z^A\\};
        \path[->,font=\scriptsize]
        (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3)
        (a-2-1) edge node[above]{$\partial^A$}  (a-2-2)
        (a-2-2) edge node[above]{$\partial^A$}  (a-2-3);
        \end{tikzpicture}
    \end{equation}
    By applying a CNOT, the state is stabilized by
    \begin{equation}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        {&X^B & Q(X^B)\\
         X^A &Q^A & Z^A\\};
        \path[->,font=\scriptsize]
        (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3)
        (a-2-1) edge node[above]{$\partial^A$}  (a-2-2)
        (a-2-2) edge node[above]{$\partial^A$}  (a-2-3)
        (a-1-2) edge node[right]{$\partial^B$}  (a-2-2)
        (a-1-3) edge node[right]{$g=\partial^A \partial^B$}  (a-2-3);
        \path[->, >=stealth, dashed, font=\scriptsize]
        (a-1-3) edge (a-2-2);
        \end{tikzpicture}
    \end{equation}
    where the dashed arrow denotes the CNOT circuit implementing $\partial^B$.
    Note that CNOT maps control $c$ and target qubit Paulis as follows
    \begin{align}
        Z_c &\mapsto Z_c\\
        Z_t &\mapsto Z_c Z_t \\
        X_c &\mapsto X_c X_t \\
        X_t &\mapsto X_t
    \end{align}
    Hence, after line 2, the state has $Z$-type physical $e_Z(Q^A)\in Q^A$ and $e_Z(X^B) +\delta^B e_Z(Q^A) \in Q(X^B)$.
    The statement then follows from Lemma \ref{lem:low-lvl-measurement}.
\end{proof}
\begin{remark}
    Note that the only difference between Algorithm \ref{alg:high-lvl-measurement} and \ref{alg:low-lvl-wCNOTs} is the measurement error as described in Remark \ref{rem:phys-meas-errs}.
\end{remark}

\subsubsection{Syndrome Extraction}
\label{sec:syndrome-extraction}
In this section, we shall apply the low level implementation of a measurement in the context of syndrome extraction of a data code.
At a high-level, we shall utilize the following corollary, which implies that if an input state has physical errors, those error can be detected via subsequential measurement without modifying the stabilizer code.

\begin{corollary}[Subsequent Measurement]
    Suppose that  $X^B$ is a copy of $X^A$ with $\partial^A = \partial^B$.
    Then Algorithm \ref{alg:low-lvl-wCNOTs} has readout $\delta^A e_Z(Q^A) +e_Z(X^B)$ with output state stabilized by $A$ with unknown physical $e_{\bullet}(Q^A)$.
\end{corollary}

Let us further elaborate the syndrome extraction as follows.

\begin{definition}[Code Gadget]
    \label{def:code-gadget}
    Given a CSS code $D=X^D\to Q^D\to Z^D$ with basis $\cX^D,\cQ^D,\cZ^D$ and (co)differential $\partial^D$ ($\delta^D$), the corresponding \textbf{code gadget} is the collection of
    \begin{itemize}
        \item Qubits $\cQ^D$ and check qubits $\cQ(X^D),\cQ(Z^D)$
        \item CNOT circuits such that a CNOT from check qubits $Q(X)$ to data qubits $Q$ can be implemented in $O(1)$ circuit depth based on the differential $\partial:Q(X)\cong X\to Q$.
        Similarly, a CNOT  from data qubits $Q$ to check qubits $Q(Z)$ can be implement in $O(1)$ depth based on $\partial:X\to Q(Z)\cong Z$.
    \end{itemize}
    We shall always assume that qubits can be initialized transversally relative to the $X$ or $Z$ basis with unknown but presumably small physical errors, and can be measured transversally perfectly.
\end{definition}

The following algorithm then addresses the initialization and subsequent measurement of a syndrome extraction process.
\begin{algorithm}
\caption{\textsc{Syndrome Extraction}}
\label{alg:syndrome-extract}
\begin{algorithmic}[1]
    \Require Data code $D$ gadget.
    \Ensure Readout
    \begin{align}
        \delta^D \tilde{e}_Z(Q^D) +e_Z(X^D) \in X^D \\
        \partial^D \tilde{e}_X(Q^D)+ e_X(Z^D) \in Z^D
    \end{align}
    for some $\tilde{e}_Z(Q^D),\tilde{e}_X(Q^D),e_Z(X^D),e_X(Z^D)$, and output state stabilized by $D$ with physical error $\tilde{e}_{\bullet}(Q^D)$ mod logicals
    \State If input state is not given, initialize $Q^D$ in $Z$-basis with unknown physical $\tilde{e}_{X}(Q^D)$
    \State Initialize $Q(X^D),Q(Z^D)$ in the $X,Z$ basis, with unknown physical $e_{Z}(X^D),e_{X}(Z^D)$, respectively
    \State Apply $O(1)$ depth CNOT circuit for $\partial$
    \State Measure out $Q(X^D)$ transversally in the $X$-basis with readout
    \begin{equation}
        \delta^D \tilde{e}_Z(Q^D) +e_Z(X^D)
    \end{equation}
    for some $\tilde{e}_Z(Q^D)$ so that output state has $Z$-type physical measurement $\tilde{e}_Z(Q^D)$ mod logicals
    \State Measure out $Q(Z^D)$ transversally in the $Z$-basis with readout
    \begin{equation}
        \partial^D \tilde{e}_X(Q^D) + e_X(Z^D)
    \end{equation}
    so that the output state has $X$-type physical measurement $e_X(Q^D)$ mod logicals
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Syndrome Extraction]
    \label{lem:syndrome-extraction}
    Algorithm \ref{alg:syndrome-extract} is correct.
    Moreover, if an input state stabilized by $D$ with physical $e_{\bullet}(Q^D)$ (e.g., subsequent measurement) is given, then the output is as given by Algorithm \ref{alg:syndrome-extract} with $\tilde{e}_{\bullet}(Q^D) = e_{\bullet}(Q^D)$.
\end{lemma}
\begin{remark}[Fault Tolerance with Threshold]
    The physical errors can then be corrected via the general error correction procedure \cite{gottesman2013fault}.
    Specifically, after $T\ge d$ rounds of subsequent syndrome extractions of Algorithm \ref{alg:syndrome-extract} where $d$ is the code distance of $D$, one can build a spacetime fault complex.
    A threshold can then be obtained by applying min-weight correction relative to the fault complex.
    See Section \ref{sec:syndrome-fault-complex} for details.
\end{remark}
\begin{proof}
    The proofs follows from Lemma \ref{lem:low-lvl-measurement}.
































\end{proof}

\subsubsection{Logical Measurement}
\label{sec:logical-measure}
In this section, we shall consider the low level implementation of a logical measurement on a data code
\begin{equation}
    D=X^D \to Q^D\to Z^D
\end{equation}
Conventionally, an ancilla $A$ is constructed which is then \textit{merged} with the data code $D$ to form a deformed code.
The checks of the deformed code are then measured in a manner similar to syndrome extraction in Section \ref{sec:syndrome-extraction}, so that the logical measurement can be extracted using the general error correction procedure \cite{gottesman2013fault} after $d(D)$ rounds of subsequential measurement.

Let us first consider the ancilla gadget.
Currently, most ancillas for logical measurements follow the same underlying procedure, which first constructs a measurement graph defined as follow.
\begin{definition}[Measurement Graph]
    Given, say an $X$-type, logical operator $\ell^{\star}_X\in Q^D$ of data code $D$, the corresponding \textbf{measurement (multi) graph} $\cG=(\cE,\cV)$ is constructed with vertices $|q\ket \in \cV$ that are in one-to-one correspondence of qubits in $q\in \ell^{\star}_X\subseteq\cQ^{D}$.
    For every $z$ check of $D$, the support of $z$ must have an even overlap with $\ell^{\star}_X$ and thus can be paired up arbitrarily.
    Define an edge $\|q\bar{q};z \ket\in \cE $ for each pair of overlapping qubits $q,\bar{q}$ and each overlapping check $z$.
\end{definition}

Given the measurement graph of logical $\ell^{\star}_X$ with associated graph complex $G=E\to V$, a corresponding cell (co)complex
\begin{equation}
    \label{eq:ancilla}
    A=X^A \to Q^A \to Z^A
\end{equation}
is then constructed with $X$-checks, qubits and $Z$-checks corresponding to the vertices, edges and faces, such that $A$ is connected as a graph with only trivial (contractible) cycles, qLDPC, has low overhead \cite{yuan2026parsimonious,williamson2026low}, and contains the graph complex $G$ as a subgraph so that a natural projection (chain) map is depicted by the diagram below
\begin{equation}
    \label{eq:subgraph}
    \begin{tikzpicture}[baseline]
    \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
    row sep=1.5em, column sep=1.5em,
    text height=1.25ex, text depth=0.25ex]
    {X^{A} &Q^A & Z^{A}\\
     V & E & \\};
    \path[->,font=\scriptsize]
    (a-1-1) edge (a-1-2)
    (a-1-2) edge (a-1-3)
    (a-2-1) edge (a-2-2)
    (a-1-1) edge node[right]{$\pi$} (a-2-1)
    (a-1-2) edge node[right]{$\pi$} (a-2-2);
    \end{tikzpicture}
\end{equation}
We refer to $A$ as a \textbf{(logical) ancilla} with respect to the measurement graph of logical $\ell^{\star}_X$.

Further note that by construction, the measurement graph induces a natural inclusion (chain) map $\iota$ depicted as follows.
\begin{equation}
    \label{eq:inclusion}
    \begin{tikzpicture}[baseline]
    \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
    row sep=1.5em, column sep=1.5em,
    text height=1.25ex, text depth=0.25ex]
    { & V & E \\
     X^{D} & Q^{D} & Z^{D}\\};
    \path[->,font=\scriptsize]
    (a-1-2) edge (a-1-3)
    (a-2-1) edge (a-2-2)
    (a-2-2) edge (a-2-3)
    (a-1-2) edge node[right]{$\iota$} (a-2-2)
    (a-1-3) edge node[right]{$\iota$} (a-2-3);
    \end{tikzpicture}
\end{equation}
such that $\iota$ maps
\begin{align}
    |q\ket &\mapsto q\\
    \|q\bar{q};z\ket &\mapsto z
\end{align}
Hence, the composition $g=\iota \pi$ defines a chain map as depicted below
\begin{equation}
    \label{eq:cone}
    \begin{tikzpicture}[baseline]
    \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
    row sep=1.5em, column sep=1.5em,
    text height=1.25ex, text depth=0.25ex]
    { & X^{A} & Q^{A} & Z^{A} \\
     X^{D} & Q^{D} & Z^{D} &\\};
    \path[->,font=\scriptsize]
    (a-1-2) edge (a-1-3)
    (a-1-3) edge (a-1-4)
    (a-2-1) edge (a-2-2)
    (a-2-2) edge (a-2-3)
    (a-1-2) edge node[right]{$g$} (a-2-2)
    (a-1-3) edge node[right]{$g$} (a-2-3);
    \end{tikzpicture}
\end{equation}
The corresponding $\cone(g:A\to D)$ is the \textbf{deformed code}, which we label as
\begin{equation}
    \cone(g) = X \to Q\to Z
\end{equation}
equipped with (co)differential $\partial$ ($\delta =\partial^{\top}$).
We refer to $g$ as the \textbf{(relative) connectivity} from the ancilla to the data code. Note that despite the construction of $A$, the map $g$ only depends on its restriction to the measurement graph, and thus $g$ defines the relative connectivity from the measurement graph to the data code.

\begin{definition}[(Relative) Connectivity Gadget]
    The \textbf{relative connectivity gadget} is a $O(1)$ depth circuit which implements a CNOT from ancilla check qubits $Q(X^A)$ to data qubits $Q^D$ based on
    \begin{equation}
        g:Q(X^A) \cong X^A \to Q^D
    \end{equation}
    and similarly for $g:Q^A \to Q(Z^D)$.
\end{definition}

\begin{theorem}[Logical Measurement]
    \label{thm:logical-measure}
    Algorithm \ref{alg:logical-measure} is correct.
    In particular, if no errors occur, then the Algorithm provides readout $s\in X$ such that the $X$-type logical $\ell^{\star}_X$ has measurement
    \begin{equation}
        \bra s|\cX^A\ket \in \F_2
    \end{equation}
    where $\cX^A\in X^A$ denotes the sum over all $X$-checks (vertices) of the ancilla.
    Moreover, if the input state is also stabilized by logical $\ell^{\star}_X$ (e.g., subsequent measurement), then we replace $\tilde{e}_Z(Q^D)\to e_Z(Q^D)$ in the output (but $\tilde{e}_Z(Q^A)$ is still unknown since it captures the logical measurement).
\end{theorem}

\begin{proof}
    After line 3, the coupled state is stabilized by the (CSS code) complex (with some errors) depicted by the following diagram
    \begin{equation}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        { & \red{X^{A}} & \darkgreen{Q^{A}} & \blue{Z^{A}} \\
         \red{X^{D}} & \darkgreen{Q^{D}} & \blue{Z^{D}} &\\};







        \end{tikzpicture}
    \end{equation}
    where, to keep the diagram simple, we have done some simplifications.
    Specifically, red nodes indicate that the corresponding (check) qubits are initialized in the $X$-basis, e.g., \red{$X^D$} indicates that the system has check qubits stabilized by the CSS code $X^D \to Q(X^D)$.
    Blue nodes indicate the corresponding qubits are initialized in the $Z$-basis, e.g., \blue{$Z^A$} indicates $Q(Z^A) \to Z^A$.
    Green node \darkgreen{$Q^{D}$} indicates the qubits in $Q^D$ are stabilized by the data CSS code $D$, while \darkgreen{$Q^A$} indicates that the qubits in $Q^A$ are initialized in the $Z$-basis.
    In all cases, there are corresponding unknown physical errors $e_{\bullet}(X),e_{\bullet}(Q),e_{\bullet}(Z)$(mod logicals).
    Equivalently, the state is stabilized by the complex with the fully drawn out diagram
    \begin{equation}
    \label{eq:logical-code-line3}
    \begin{tikzpicture}[baseline]
    \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=20pt},
    row sep=0.2em, column sep=1.5em,
    text height=1.25ex, text depth=0.25ex]
    {&\red{X} & \red{Q(X)}\\ \\
    &\darkgreen{Q^A} & \darkgreen{Z(Q^A)}\\
     \darkgreen{X'^D} &\darkgreen{Q^D} & \darkgreen{Z'^D}\\ \\
     \blue{Q(Z)} & \blue{Z}&\\};
    \path[->,red,font=\scriptsize]
    (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3);
    \path[->,blue,font=\scriptsize]
    (a-6-1) edge node[above]{$\rm{id}$}  (a-6-2);
    \path[->,green!40!black,font=\scriptsize]
