    (a-3-2) edge node[]{$\oplus$}  (a-4-2)
    (a-3-3) edge node[]{$\oplus$}  (a-4-3);
    \end{tikzpicture}
    \end{equation}
    where $X'^D,Z'^D$ denote copies of $X^D,Z^D$ which were stabilized due to the input.

    After line 4, the system is stabilized (with some errors) by
    \begin{equation}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        { & \blue{X^{A}} & \darkgreen{Q^{A}} & \red{Z^{A}} \\
         \blue{X^{D}} & \darkgreen{Q^{D}} & \red{Z^{D}} &\\};
        \path[->,font=\scriptsize]
        (a-1-2) edge (a-1-3)
        (a-2-1) edge (a-2-2)
        (a-1-2) edge node[right]{$g$} (a-2-2)
        (a-1-3) edge (a-1-4)
        (a-2-2) edge (a-2-3)
        (a-1-3) edge node[right]{$g$} (a-2-3);
        \end{tikzpicture}
    \end{equation}
    where the colored arrows indicate that we have omitted other arrows so that overall sequence is a complex if the check qubits are also shown.
    Equivalently, the full diagram is given by (compare with \cite{yuan2026unified})
    \begin{equation}
    \label{eq:logical-code-line4}
    \begin{tikzpicture}[baseline]
    \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=20pt},
    row sep=0.15em, column sep=1.5em,
    text height=1.25ex, text depth=0.25ex]
    {&\red{X} & \red{Q(X)}\\ \\
    &\darkgreen{Q^A} & \darkgreen{Z(Q^A)}\\
     \darkgreen{X'^D} &\darkgreen{Q^D} & \darkgreen{Z'^D}\\ \\
     \blue{Q(Z)} & \blue{Z}&\\};
    \path[->,red,font=\scriptsize]
    (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3);
    \path[->,blue,font=\scriptsize]
    (a-6-1) edge node[above]{$\rm{id}$}  (a-6-2);
    \path[->,green!40!black,font=\scriptsize]
    (a-3-2) edge node[above]{$\rm{id}$}  (a-3-3)
    (a-4-1) edge node[above]{$\partial^D$}  (a-4-2)
    (a-4-2) edge node[above]{$\partial^D$}  (a-4-3);
    \draw[green!40!black]
    (a-3-2) edge node[]{$\oplus$}  (a-4-2)
    (a-3-3) edge node[]{$\oplus$}  (a-4-3);
    \path[->,font=\scriptsize]
    (a-1-2) edge node[right]{$\partial$} (a-3-2)
    (a-1-3) edge node[right]{$\cdots$} (a-3-3)
    (a-4-2) edge node[right]{$\partial$} (a-6-2)
    (a-4-1) edge node[right]{$\cdots$} (a-6-1);
    \end{tikzpicture}
    \end{equation}
    where are vertical maps form a chain map.
    Note that as shown in Lemma \ref{lem:low-lvl-measurement}, the omitted arrows (which resemble $g$ in Eq. \eqref{eq:low-lvl-measurement}) are irrelevant once we measure out the check qubits.
    Note that CNOT maps control $c$ and target qubit Paulis as follows
    \begin{align}
        Z_c &\mapsto Z_c\\
        Z_t &\mapsto Z_c Z_t \\
        X_c &\mapsto X_c X_t \\
        X_t &\mapsto X_t
    \end{align}
    Therefore, the system maps physical errors on qubits given as follows:
    \begin{align}
        Q(X): e_Z(X) &\mapsto e_Z(X) +\delta e_Z(Q) \\
        Q: e_{\bullet} (Q) &\mapsto e_{\bullet}(Q) \\
        Q(Z): e_X(Z) &\mapsto e_X(Z) +\partial e_X(Q)
    \end{align}
    where
    \begin{align}
        e_{\bullet}(Q) = e_{\bullet}(Q^A) \oplus e_{\bullet}(Q^D)
    \end{align}
    where recall that we can take $e_Z(Q^A) =0$ since $Q^A$ is initialized in the $Z$-basis.

    By Lemma \ref{lem:low-lvl-measurement}, measuring out the check qubits $Q(X)=Q(X^A) \oplus Q(X^D)$ will output the readout
    \begin{equation}
        \delta \tilde{\ell}_Z(Q) + e_Z(X) +\delta e_Z(Q) \in X
    \end{equation}
    for some $Z$-type logical $\tilde{\ell}_Z(Q)$ of the green portion in Eq. \eqref{eq:logical-code-line3}.
    In particular, since ancillas \darkgreen{$Q^A$} are initialized in the $Z$-basis of Eq. \eqref{eq:logical-code-line3}, $\tilde{\ell}_Z(Q^A)$ is arbitrary in \darkgreen{$Q^A$}.
    Similarly, since \darkgreen{$Q^D$} are stabilized by the data code $D$ due to the input, we see that $\tilde{\ell}_Z(Q^D)$ is a logical of data code $D$.
    Let
    \begin{equation}
        \tilde{e}_Z(Q) = e_Z(Q) +\tilde{\ell}_Z(Q)
    \end{equation}
    Then we see that line 5 is correct.
    Specifically, the state after line 5 is stabilized by $X$ Paulis of the form $\im \partial$ on $Q$ with physical errors $\tilde{e}_Z(Q)$ (mod logicals), where we have ignored the stabilizers on the $Z$-check qubits $Q(Z)$, since they will be measured out in the next line.
    Similarly, the state after line 5 is stabilized by $Z$ Pauli of the form
    \begin{equation}
        (Q^A \oplus \im \delta^D) \cap (\im \partial)^\perp
    \end{equation}
    with physical errors $e_X(Q)$. Note that if $q^A \oplus \delta^D z^D \in (\im \partial)^\perp =\ker \delta$, then $\delta^A (q^A +g^{\top}z^D)=0$ and thus $q^A \in g^{\top} z^D +\im \delta^A$ where we utilized the fact that the ancilla has no internal logicals so that $\ker \delta^A = \im \delta^A$. Hence,
    \begin{equation}
        (Q^A \oplus \im \delta^D) \cap (\im \partial)^\perp = \im \delta
    \end{equation}

    By Lemma \ref{lem:low-lvl-measurement}, measuring out the check qubits $Q(Z)=Q(Z^A) \oplus Q(Z^D)$ will output the readout
    \begin{equation}
        \partial \ell_X(Q) + e_X(Z) +\partial e_X(Q) \in Z
    \end{equation}
    for some $X$-type logical $\ell_X(Q)$ of the stabilizer code after line 5. However, note that after line 5, the state is stabilize by $Z$-check of the form $\im \delta$, and thus $\partial \ell_X(Q)=0$ so that the readout is
    \begin{equation}
        e_X(Z) +\partial e_X(Q) \in Z
    \end{equation}
    and thus the state has physical $X$-error $e_X(Q) +\ell_X(Q)=e_X(Q)$ mod logicals so that line 6 is correct.
    More specifically, the state after line 6 is stabilized by the deformed code $\cone(g)$ with errors $\tilde{e}_Z(Q),e_X(Q)$ mod logicals.

    By Lemma \ref{lem:low-lvl-measurement}, we see that measuring ancilla qubits $Q^A$ transversally gives readout
    \begin{equation}
        s_X(Q^A) + e_X(Q^A) \in Q^A
    \end{equation}
    with $s_X(Q^A) \in \ell(Q^A)$ where $\ell(Q^A)$ is the projection of some $\ell(Q)\in \ker \partial$ onto $Q^A$. In particular, we see that $\ell(Q^A) \in \ker \partial^A$ and thus $s_X(Q^A) = \partial ^A x^A$ since the ancilla only has trivial logicals.
    Also note that $\partial^D \ell(Q^D) = g\ell(Q^A)=\partial^D gx^A$.
    The output is then stabilized by
    \begin{itemize}
        \item $X$-Paulis of the form $\im \delta^D$ and $\ell^D$ with error $\tilde{e}_Z(Q^D)$ mod logicals
        \item $Z$-Paulis of the form $\im \partial^D$ with error $e_X(Q^D) +\ell(Q^D)=e_X(Q^D) +gx^A$ mod logicals.
    \end{itemize}

    In particular, note that the measurement of $\ell^D$ is given by
    \begin{align}
        \bra \tilde{e}_Z(Q^D)|\ell^D\ket &= \bra \tilde{e}_Z(Q^D)| g\cX^A\ket \\
        &= \bra \delta \tilde{e}_Z(Q)|\cX^A\ket
    \end{align}
    where we utilized the fact that $\partial^A \cX^A =0$. Note that if no errors occurs, then we obtain readout $\delta \tilde{e}_Z(Q)$ and thus can determine the logical measurement exactly.
\end{proof}

\begin{algorithm}
\caption{\textsc{Logical Measurement}}
\label{alg:logical-measure}
\begin{algorithmic}[1]
    \Require An input state stabilized by data code $D$ with unknown physical $e_{\bullet}(Q^D)$.
    Data code gadget $D$. Ancilla code gadget $A$ with respect to $X$-type logical $\ell^{\star}_X$ and relative connectivity gadget $g$.
    \Ensure Readout
    \begin{align}
        \delta \tilde{e}_Z(Q) +e_Z(X) \in X \\
        \partial e_X(Q)+ e_X(Z) \in Z \\
        \partial^A x^A +e_X(Q^A)\in Q^A
    \end{align}
    where
    \begin{align}
        e_X(Z) & = e_X(Z^A) \oplus e_X(Z^D) \\
        e_X(Q) & = e_X(Q^A) \oplus e_X(Q^D) \\
        e_Z(X) & = e_Z(X^A) \oplus e_Z(X^D) \\
        \tilde{e}_Z(Q) &= \tilde{e}_Z(Q^A) \oplus \tilde{e}_Z(Q^D)
    \end{align}
    where non-tilde elements $e$ denote (presumably small) initialization errors, and
    \begin{equation}
        \delta^D \tilde{e}_Z(Q^D) =\delta^D e_Z(Q^D)
    \end{equation}
    The output state is stabilized by data code $D$ and $X$-type logical $\ell^{\star}_X$ with physical $\tilde{e}_Z(Q^D),e_X(Q^D)+gx^A$.
    In particular, $\ell^{\star}_X$ has measurement
    \begin{equation}
        \bra \tilde{e}_Z(Q)|\ell^{\star}_X\ket = \bra \delta \tilde{e}_Z(Q)| \cX^A\ket \in \F_2
    \end{equation}
    where $\cX^A$ is the sum over all $X$-checks (vertices) in $X^A$.
    \State Initialize $Q^{A}$ in the $Z$ basis with unknown error $e_{X}(Q^A)$, and $e_{Z}(Q^A)=0$
    \State Initialize $Q(X)=Q(X^A)\oplus Q(X^D)$ in the $X$ basis with unknown error
    \begin{equation}
        e_Z(X) = e_Z(X^A) \oplus e_Z(X^D)
    \end{equation}
    \State Initialize $Q(Z)=Q(Z^A) \oplus Q(Z^D)$ in the $Z$ basis with unknown error
    \begin{equation}
        e_X(Z) = e_X(Z^A) \oplus e_X(Z^D)
    \end{equation}
    \State Apply $O(1)$ depth CNOT circuit for $\partial^D,\partial^A,g$
    \State Measure out $Q(X)$ transversally in the $X$-basis with readout
    \begin{equation}
        \delta \tilde{e}_Z(Q) +e_Z(X) \in X
    \end{equation}
    for some $\tilde{e}_Z(Q)\in Q$
    such that $\delta^D \tilde{e}_Z(Q^D) = \delta^D e_Z(Q^D)$ so that the output state has physical error $\tilde{e}_Z(Q)$ mod logicals.
    \State Measure out $Q(Z)$ transversally in the $Z$-basis with readout
    \begin{equation}
        \partial e_X(Q)+ e_X(Z) \in Z
    \end{equation}
    so that the output state has physical error $e_X(Q)$ mod logicals.
    \State Measure out $Q^A$ transversally in the $Z$-basis (opposite of logical type $\ell^{\star}_X$) with readout
    \begin{equation}
        \partial^A x^A +e_X(Q^A)\in Q^A
    \end{equation}
    for some $x^A\in X^A$.
    so that the output state is stabilized by
    \begin{itemize}
        \item $X$-Paulis in $\im \partial^D + \ell^{\star}_X$ with physical $\tilde{e}_Z(Q^D)$ mod logicals (not only commute with $X$-Paulis of $D$ but also $\ell^{\star}_X$)
        \item $Z$-Paulis in $\im \delta^D$ with physical $e_X(Q^D) + gx^A$ mod logicals
    \end{itemize}
\end{algorithmic}
\end{algorithm}

\subsection{Low Level Non-CSS Measurement}
\label{sec:low-lvl-non-CSS-measure}

\begin{lemma}[Low Level]
\label{lem:low-lvl-non-CSS-measurement}
Algorithm \ref{alg:low-lvl-non-CSS-measurement} is correct.
\end{lemma}

\begin{proof}
    By Lemma \ref{lem:overcomplete-non-CSS-physicals}, the transversal measurement outcome $s(\bar{X}^A)\in Q(\bar{X}^A)$ (in the $Z$-sector of the ancilla qubits $P^A$) must satisfy
    \begin{equation}
        e(P) + s(\bar{X}^A) \in \ker \hat{\sigma} +\left(Q(X^{A}) \oplus P^D\right)
    \end{equation}
    Hence, there must exists $\ell =0\oplus \ell (P^D) \oplus \ell(\bar{X}^A)\in \ker \hat{\sigma}$ and $x^{A}\in X^{A}$ such that
    \begin{equation}
        \begin{pmatrix}
            e(X^{A}) \\
            e(P^D) \\
            e(\bar{X}^A)
        \end{pmatrix}
        +
        \underbrace{
        \begin{pmatrix}
            0 \\
            \ell(P^D) \\
            \ell(\bar{X}^A)
        \end{pmatrix}
        +
        \sigma x^A
        }_{\in  \ker\hat{\sigma}}
        =
        \begin{pmatrix}
            0 \\
            0 \\
            s
        \end{pmatrix}
        +
        \begin{pmatrix}
            Q(X^A) \\
            P^D \\
            0
        \end{pmatrix}
    \end{equation}
    Hence,
    \begin{equation}
        s=e(\bar{X}^A) +\ell(\bar{X}^A)
    \end{equation}
    where we utilized the fact that the defect map $p=0$.
    As we shall see in Algorithm \ref{alg:low-lvl-non-CSS-wCNOTs}, this is due to measurement of commuting Paulis so that $\hat{g}g=0$.
    Since $\ell$ is a logical, we see that $\ell(\bar{X}^A) = \hat{g} \ell(P^D)$ where $\ell(P^D)\in \ker \hat{\sigma}^D$ is a logical of the data code $D$ and thus the readout is
    \begin{equation}
        e(\bar{X}^A) + \hat{g} \ell(P^D)
    \end{equation}
    Again, by Lemma \ref{lem:overcomplete-non-CSS-physicals}, we see that the output state is stabilized with physical measurement $e(P)+\ell+\sigma x^{A}$, with stabilizer of the form
    \begin{align}
        &\im \sigma \cap (Q(X^A)\oplus P^D) +Q(X^{A}) \\
        &= Q(X^{A}) \oplus \underbrace{(\im \sigma^D \cap \ker \hat{g} + \im g)}_{P^D}
    \end{align}
    Since we discard ancilla qubits $P^A = Q(X^{A} ) \oplus Q(\bar{X}^A)$, we only care about the phase info in $\im \sigma^D \cap \ker \hat{g}$.
    In particular, we see that if $s^D\in S^D$ is such that $\sigma^D s^D \in \im \sigma^D \cap \ker \hat{g}$, then the output state is stabilized by the Pauli element corresponding to $\sigma^D s^D$ with measurement
    \begin{align}
        &\Lambda^D(e(P^D) +\ell(P^D) +gx^{A},\sigma^D s^D) \\
        &=\Lambda^D(e(P^D)+\ell(P^D),\sigma^D s^D) +(\hat{g} \sigma^D s^D)(x^{A})\\
        &= \Lambda^D(e(P^D)+\ell(P^D),\sigma^D s^D)
    \end{align}
    Similarly, note that
    \begin{equation}
        \Lambda^D (g x^{A} ,g\tilde{x}^A) =  0
    \end{equation}
    where we used the fact that $\hat{g} g=0$.
    Hence, the output state has physical measurement $e(P^D) +\ell(P^D)$ mod logicals.
\end{proof}

\begin{lemma}[High Level]
    Algorithm \ref{alg:high-lvl-non-CSS-measurement} is correct.
\end{lemma}

