\begin{algorithm}
\caption{\textsc{Low-Level non-CSS with CNOTs}}
\label{alg:low-lvl-non-CSS-wCNOTs}
\begin{algorithmic}[1]
    \Require State stabilized by non-CSS code with symplectic complex
    \begin{equation}
        D= S^D \xrightarrow{\sigma^D} P^D \xrightarrow{\hat{\sigma}^D} {\bar{S}^{D}}
    \end{equation}
    with (unknown) physical $e(P^D)$ mod logicals.


    \Ensure Measure commuting Paulis in $g:X^{A} \to P^D$ with readout
    \begin{equation}
        \hat{g}\tilde{e}(P^D) +e(\bar{X}^A) \in \bar{X}^A
    \end{equation}
    where $e(\bar{X}^A)$ is unknown, and $\tilde{e}(P^D)+e(P^D) \in \ker \hat{\sigma}^D$ is some unknown logical of $D$, and the output state is stabilized by Paulis of the form
    \begin{equation}
        \im \sigma^D \cap \ker \hat{g} +\im g
    \end{equation}
    with physical $\tilde{e}(P^D)$ mod logicals.
    \State Initialize ancilla qubits $P^A=Q(X^{A})\oplus Q(\bar{X}^A)$ transversally in $X$-basis with (unknown) physicals in the $Z$-sector $e(\bar{X}^A)\in Q(\bar{X}^A)\cong \bar{X}^A$  mod logicals
    \State Apply CNOT and CZ circuits from ancilla qubits to data qubits based on $g_X,g_Z$ (defined as the projection of $g$ onto the $X$- and $Z$-sector), respectively
    \State Measure out $P^A$ in the $X$-basis (correspond to $Q(X^{A})$) with (physical) measurement in the $Z$-sector $\in Q(\bar{X}^A) \cong \bar{X}^A$
\end{algorithmic}
\end{algorithm}

\begin{lemma}[Relation]
    \label{lem:low-lvl-non-CSS-wCNOTs}
    Algorithm \ref{alg:low-lvl-non-CSS-wCNOTs} is correct.
\end{lemma}
\begin{proof}
    After initialization (line 1), the state is stabilized by
    \begin{equation}
        \begin{tikzpicture}[baseline]
        \matrix(a)[matrix of math nodes, nodes in empty cells, nodes={minimum size=25pt},
        row sep=1.5em, column sep=1.5em,
        text height=1.25ex, text depth=0.25ex]
        {&X^{{A}} & Q(X^{{A}})\\
         S^D &P^D & \bar{S}^{D}\\
         Q(\bar{X}^A) & \bar{X}^A &\\};
        \path[->,font=\scriptsize]
        (a-1-2) edge node[above]{$\rm{id}$}  (a-1-3)
        (a-2-1) edge node[above]{$\sigma^{D}$}  (a-2-2)
        (a-2-2) edge node[above]{$\hat{\sigma}^D$}  (a-2-3)




        (a-3-1) edge node[above]{$\mathrm{id}$} (a-3-2);
        \end{tikzpicture}
    \end{equation}

    Note that CNOT maps control $c$ and target qubit Paulis as follows
    \begin{align}
        X_c &\mapsto X_c X_t \\
        X_t &\mapsto X_t \\
        Z_t &\mapsto Z_c Z_t \\
        Z_c &\mapsto Z_c
    \end{align}
    Hence, if a CNOT circuit is applied from ancilla qubits $Q(X^{A})\cong X^{A}$ to data qubits $Q^D\cong Q_X^D$ based on $g_X:X^{A}\to Q_X^D$, then the stabilizer map $\sigma$ of the height-2 cone
    \begin{equation}
        \mapsto
        \begin{pmatrix}
            \rm{id} &&& \\
            g_X & \rm{id} && \\
            && \rm{id} &\\
            && g_X^{\top} &\rm{id}
        \end{pmatrix} \sigma
    \end{equation}
    where the matrix is relative to
    \begin{equation}
        Q(X^{A})\oplus Q_X^D\oplus Q_Z^D\oplus Q(\bar{X}^A)
    \end{equation}
    Note that the matrix is block-diagonal with respect to the $X,Z$-decomposition, i.e., $X,Z$ Paulis are mapped to $X,Z$ Paulis, respectively.
    This corresponds to a diagram of the height-2 cone with $p=0$.

    Similarly, a CZ maps control $c$ and target qubit Paulis as follows
    \begin{align}
        X_c &\mapsto X_c Z_t \\
        X_t &\mapsto Z_c X_t \\
        Z_t &\mapsto Z_t \\
        Z_c &\mapsto Z_c
    \end{align}
    Hence, if a CZ is applied from ancilla qubits $Q(X^{A})\cong X^{A}$ to data qubits $Q^D\cong Q_Z^D$ based on $g_Z:X^{A} \to Q_Z^D$, then the stabilizer map $\sigma$ of the height-2 cone
    \begin{equation}
        \mapsto
        \begin{pmatrix}
            \rm{id} &&& \\
             & \rm{id} && \\
            g_Z && \rm{id} &\\
            &  g_Z^{\top} &&\rm{id}
        \end{pmatrix} \sigma
    \end{equation}
    where we note that the matrix representation is no longer block-diagonal, i.e., it mixes $X,Z$ Paulis.
    Note that the matrix is lower-triangular and thus corresponds to a similar height-2 cone diagram with $p=0$.

    In particular, note that the application of CNOT and CZ circuits results in matrix
    \begin{equation}
        \begin{pmatrix}
            \rm{id} &&& \\
            g_X & \rm{id} && \\
            g_Z && \rm{id} &\\
            &  g_Z^{\top} & g_X^{\top} &\rm{id}
        \end{pmatrix}
        =
        \begin{pmatrix}
            \rm{id} && \\
            g & \rm{id} & \\
            &  \hat{g} &\rm{id}
        \end{pmatrix}
    \end{equation}
    Hence, physical $e(P^D)\oplus e(\bar{X}^A)$ maps to
    \begin{equation}
        \mapsto e(P^D)\oplus (\hat{g} e(P^D) +e(\bar{X}^A))
    \end{equation}
    The statement then follows from Lemma \ref{lem:low-lvl-non-CSS-measurement}.
\end{proof}
\begin{remark}
    Note that the only difference between Algorithm \ref{alg:high-lvl-non-CSS-measurement} and \ref{alg:low-lvl-non-CSS-wCNOTs} is the measurement error as described in Remark \ref{rem:phys-meas-errs}.
\end{remark}

\subsubsection{Non-CSS Syndrome Extraction}
\label{sec:non-CSS-syndrome-extraction}
In this section, we shall apply the low level implementation of a measurement in the context of syndrome extraction of a data code.
At a high-level, we shall utilize the following corollary, which implies that if an input state has physical errors, those error can be detected via subsequential measurement without modifying the stabilizer code.

\begin{corollary}[Subsequent Measurement]
    Suppose that  $X^{A}$ is a copy of $S^D$ with $g = \sigma^D$.
    Then Algorithm \ref{alg:low-lvl-non-CSS-wCNOTs} has the same output but with $\tilde{e}(P^D)=e(P^D)$.
\end{corollary}

Let us further elaborate the syndrome extraction as follows.

\begin{definition}[Non-CSS Code Gadget]
    \label{def:non-CSS-code-gadget}
    Consider a non-CSS code $D=S^D\to P^D\to \bar{S}^D$ in the form of a symplectic complex with (basis) checks $\cS^D$ and ($X,Z$-sector) qubits $\cQ_X^D,\cQ_Z^D\cong \cQ^D$ and stabilizer map $\sigma^D$, and isometry $\phi^D:S^D\to \bar{S}^D$.
    The corresponding \textbf{code gadget} is the collection of
    \begin{itemize}
        \item qubits $\cQ$ and check qubits $\cQ(S^D)$ where $\cQ(S^D)$ is in one-to-one correspondence with checks $\cS^D$.
        For notation consistency, write $Q(S^D)$ to be the $\F_2$ space generated by $\cQ(S^D)$ so that the identity map is an isometry between $Q(S^D)\cong S^D$.
        \item CNOT circuits such that a CNOT from check qubits $Q(S^D)$ to data qubits $Q^D$ can be implemented in $O(1)$ circuit depth based on the $X$-sector generator $\sigma^D_X:Q(S^D)\cong S^D\to Q_X^D$ of $\sigma^D$.
        Similarly, a CZ from check qubits $Q(S^D)$ to data qubits $Q^D$ can be implemented in $O(1)$ depth based on the $Z$-sector generator $\sigma^D_Z:Q(S^D)\cong S^D\to Q_Z^D$.
    \end{itemize}
    We shall always assume that qubits can be initialized transversally relative to the $X$ or $Z$ basis with unknown physical errors (mod logicals), and can be measured transversally perfectly.
\end{definition}

The following two algorithms then addresses the initialization and subsequent measurement of a syndrome extraction process.
\begin{algorithm}
\caption{\textsc{non-CSS Syndrome Extraction}}
\label{alg:non-CSS-syndrome-extract}
\begin{algorithmic}[1]
    \Require Data code $D$ gadget
    \Ensure Readout
    \begin{align}
        \hat{\sigma}^D \tilde{e}(P^D) +e(\bar{S}^D) \in \bar{S}^{D}
    \end{align}
    for some $\tilde{e}(P^D),e(\bar{S}^D)$, and output state stabilized by $D$ with physical $\tilde{e}(P^D)$
    \State Initialize $Q(S^D)$ in the $X$ basis, with unknown physical $e(\bar{S}^D)$ in the $Z$-sector
    \State Apply $O(1)$ depth CNOT and CZ circuit for $\sigma^D:S^D\to P^D$
    \State Measure out $Q(S^D)$ transversally in the $X$-basis with readout
    \begin{equation}
        \hat{\sigma}^D \tilde{e}(P^D) +e(\bar{S}^D)
    \end{equation}
    for some $\tilde{e}(P^D)$ so that the output state has physical measurement $\tilde{e}(P^D)$ mod logicals
\end{algorithmic}
\end{algorithm}

\begin{lemma}[non-CSS Syndrome Extraction]
    \label{lem:non-CSS-syndrome-extraction}
    Algorithm \ref{alg:non-CSS-syndrome-extract} is correct.
    Moreover, if an input state stabilized by $D$ with physical $e(P^D)$ (e.g., subsequent measurement) is given, then the output is as given by Algorithm \ref{alg:non-CSS-syndrome-extract} with $\tilde{e}(P^D) = e(P^D)$.
\end{lemma}
\begin{remark}[Fault Tolerance with Threshold]
    The physical errors can then be corrected via the general error correction procedure \cite{gottesman2013fault}.
    Specifically, after $T\ge d(D)$ rounds of subsequent syndrome extractions of Algorithm \ref{alg:non-CSS-syndrome-extract} where $d(D)$ is the code distance of $D$, one can build a spacetime fault complex.
    A threshold can then be obtained by applying min-weight correction relative to the fault complex.
    See Section \ref{sec:non-CSS-syndrome-fault-complex} for details.
\end{remark}
\begin{proof}
    The proofs follows from Lemma \ref{lem:low-lvl-non-CSS-wCNOTs}.
































\end{proof}

