Let $J_0:\mathcal H_{\B\Y}\longrightarrow\mathcal H_{\X\B\f\Y}$ satisfy
\begin{equation}
  J_0(\ket J_\B\ket y_\Y)
   =\ket{0^r}_\X\ket J_\B\ket0_\f\ket y_\Y.
  \label{eq:J0-definition}
\end{equation}

The following lemma shows that $W$ is a block encoding of $V$.
\begin{lemma}
\label{lem:uniform-block}
Let $\rho=Dg$. Then
\begin{equation}
  J_0^\dagger WJ_0
  =\frac1D\sum_{I,J=0}^{D-1}
      \ket I\!\bra J_\B\otimes (C_{IJ})_{\Y}
  =\frac V\rho,
  \label{eq:uniform-clean-block}
\end{equation}

\end{lemma}

\begin{proof}
For $0\le J <D$ and $0\le y < b$, the initial state
is
\begin{equation}
  \ket{0^r}_\X\ket J_\B\ket0_\f\ket y_\Y.
\end{equation}
After the first $H_D$ on $\X$, it is
\begin{equation}
  \frac1{\sqrt D}\sum_{I=0}^{D-1}
    \ket I_\X\ket J_\B\ket0_\f\ket y_\Y.
  \label{eq:W-state-after-first-H}
\end{equation}
Applying SELECT, we have
\begin{align}
  &\frac1{\sqrt D}\sum_{I=0}^{D-1}
    \ket I_\X\ket J_\B \operatorname{Hal}(C_{IJ})(\ket0_\f\ket y_\Y)\\
    &=\frac1{\sqrt D}\sum_{I=0}^{D-1}
    \ket I_\X\ket J_\B \ket0_\f C_{IJ} \ket y_\Y + \ket{\perp},
  \label{eq:W-state-after-select}
\end{align}
where 
\begin{equation}
  \ket{\perp}\defeq\frac1{\sqrt D}\sum_{I=0}^{D-1}
    \ket I_\X\ket J_\B \ket1_\f (I-C_{IJ}^\dagger C_{IJ})^{1/2}\ket y_\Y  
\end{equation}
and $\ket{\perp}$ is orthogonal to the first component. For every computational basis label \(\ket{J}\), $\bra{0^r} H_D\ket J=1/{\sqrt D}$. After applying the $H_D$ on $\B$, we have
\begin{align}
    &\frac1{\sqrt D}\sum_{I=0}^{D-1}
    \ket I_\X H_D\ket J_\B \ket0_\f C_{IJ} \ket y_\Y +(H_D)_{\B}\ket{\perp}\\
    =&\frac1{D}\sum_{I=0}^{D-1}
    \ket I_\X \ket {0^r}_\B \ket0_\f C_{IJ} \ket y_\Y + \ket{\perp'},
\end{align}
where
\begin{equation}
    \ket{\perp'}\defeq(H_D)_{\B}\ket{\perp} + \frac{1}{D}\sum_{I=0}^{D-1}\sum_{K=1}^{D-1}\ket{I}_{\X}\sigma_{JK}\ket{K}_{\B}\ket{0}_{\f}C_{IJ}\ket{y}_{\Y}
\end{equation}
for some $\sigma_{JK}\in\{\pm 1\}$ and $\ket{\perp'}$ is orthogonal to the first component.
The final swap maps the first component to
\begin{equation}
  \frac1D\sum_{I=0}^{D-1}
    \ket0_\X\ket I_\B\ket0_\f C_{IJ}\ket y_\Y.
  \label{eq:W-clean-state-after-swap}
\end{equation}
The image of \(\ket{\perp'}\) under the swap has either
\(\X\ne0^r\) or \(\f=1\), and is therefore annihilated by \(J_0^\dagger\).

Applying \(J_0^\dagger\) leaves
\begin{align}
  J_0^\dagger WJ_0(\ket{J}_{\B}\ket{y}_{\Y})
  &=\frac1D\sum_{I=0}^{D-1}
      \ket I_{\B}C_{IJ}\ket y_{\Y}\notag\\
  &=\frac1{Dg}\sum_{I=0}^{D-1}
      \ket I_{\B}V_{IJ}\ket y_{\Y}
   =\frac V{Dg}(\ket J_{\B}\ket y_{\Y}).
  \label{eq:clean-action-on-block-basis}
\end{align}
This completes the proof.
\end{proof}

We introduce $\iota$ to denote the isometry that appends the clean ancillary space required by the chosen Clifford+\(T\)
implementation of \(W\). Let
\begin{equation}\label{eq:J}
    J=\iota J_0.
\end{equation}
The following lemma shows the $T$-count of unitary $W$ in Lemma \ref{lem:uniform-block}.
\begin{lemma}
\label{lem:compiled-base}
Assume \(k<n\). For every \(0<\delta<1/2\), there is a Clifford+T circuit unitary
\(\widetilde W\) such that
\begin{equation}
  \norm{\widetilde W\,\iota-\iota W}\le\delta.
  \label{eq:compiled-W-guarantee}
\end{equation}
Its $T$-count and ancilla-count are both
\begin{equation}
  O\!\left(d\sqrt{k+\log (1/\delta)}+b^2(k+\log (1/\delta))\right).
  \label{eq:compiled-base-cost}
\end{equation}
Moreover, for $A=J^\dagger\widetilde WJ$,
\begin{equation}
  \norm{A-\rho^{-1}V}\le\delta.
  \label{eq:actual-clean-block-bound}
\end{equation}
\end{lemma}
\begin{proof}
As discussed above, $W$ consists of $2$ Walsh transforms $H_D=H^{\otimes r}$, a $(2r,k+1)$-UCU $\SELECT$ and a swap operator $\operatorname{SWAP}(\X,\B)$. Applying Lemma~\ref{lem:tan-controlled} with error \(\delta\),
we obtain a Clifford+\(T\) implementation of \(\SELECT\) using
\(
  O\!\left(
    d\sqrt{k+\log(1/\delta)}
    +b^2\bigl(k+\log(1/\delta)\bigr)
  \right)
\)
\(T\) gates and clean ancillas.  Since \(H_D\) and
\(\operatorname{SWAP}(\X,\B)\) are Clifford operations, adjoining
them does not increase the \(T\)-count or the approximation error.
Thus the resulting circuit \(\widetilde W\) is a Clifford+\(T\)
circuit with the claimed bounds.

Now use \(J=\iota J_0\), \(\iota^\dagger\iota=I\):
\begin{align}
  \norm{A-\rho^{-1}V}
   &=\norm{
       J_0^\dagger\iota^\dagger\widetilde W\iota J_0
       -J_0^\dagger WJ_0
     }\notag\\
   &=\norm{
       J_0^\dagger\iota^\dagger
       (\widetilde W\iota-\iota W)J_0
     }\notag\\
   &\le
     \norm{J_0^\dagger}\norm{\iota^\dagger}
     \norm{\widetilde W\iota-\iota W}\norm{J_0}\notag\\
   &\le\delta.
  \label{eq:actual-clean-block-expanded}
\end{align}
All embeddings are isometries and hence have norm one.
\end{proof}

\section{$T$-count for general unitary synthesis}
\label{sec:amplification}

In this section, we first use Quantum Singular Value Transformation (QSVT) to construct a circuit for the block-flattened unitary and then use this circuit to obtain a Clifford+\(T\) implementation of a general unitary.

Put
\begin{equation}
  c\defeq\rho^{-1}.
  \label{eq:c-definition}
\end{equation}
In Eq.~\eqref{eq:uniform-clean-block}, since $W$ is a unitary, 
\begin{equation}
    \norm{J_0^\dagger W J_0}=\norm{\frac{V}{\rho}}=\frac{1}{\rho}=c\le 1.
\end{equation}
Moreover, $g\le 1$ implies $\rho=Dg\le D\le d$. Therefore
\begin{equation}
   0 < c \le 1,\qquad Q=\Theta(\rho)=O(d).
\end{equation}

\subsection{Quantum circuit for the block-flattened unitary}
The next lemma constructs a
bounded odd polynomial that equals one exactly at the specified point
\(c\).  It also explains precisely which QSP results make that
polynomial implementable.

\begin{lemma}
\label{lem:exact-response}
For every \(0<c\le1\), there is an odd integer $Q=\Theta(1/c)$ and a degree-$Q$ polynomial $P(x)\in\mathbb{C}[x]$
such that $P(x)$ satisfies $P(c)=1$ and
\begin{enumerate}
        \item $P$ has parity-$(Q\mod 2)$,
        \item $\forall x\in[-1,1]$: $|P(x)|\le 1$,
        \item $\forall x\in (-\infty,-1]\cup [1,\infty)$: $|P(x)|\ge 1$,
    \end{enumerate}
\end{lemma}
\begin{proof}
    See the proof in Appendix \ref{append:proof-restate}.
\end{proof}
Recall the QSVT in \cite{Gilyen2019}. Let 
\begin{equation}\label{eq:projector}
    \Pi=JJ^\dagger
\end{equation}
be the projector onto the subspace in which all $a$ acillas are zero. For $cV$, there exists a unitary $W$ such that 
{\begin{equation}
    J^\dagger W J=cV, \qquad \Pi W \Pi=J(cV)J^\dagger.
\end{equation}
by Lemma \ref{lem:uniform-block}.} 

For the odd-degree-$Q$ polynomial $P(x)$ in Lemma \ref{lem:exact-response}, there exists $\Phi=(\phi_1,\phi_2,\ldots,\phi_{Q})\in \mathbb{R}^Q$, we have
\begin{equation}
    P^{(SV)}({J(cV)J^\dagger})=P^{(SV)}(\Pi W \Pi)=\Pi U_{\Phi} \Pi{=JVJ^\dagger},
\end{equation}
where 
\begin{equation}\label{eq:QSVT-circuit}
    U_{\Phi}=e^{i\phi_1(2\Pi-I)}W\prod_{j=1}^{\frac{Q-1}2}e^{i\phi_{2j}(2\Pi-I)}W^\dagger e^{i\phi_{2j+1}(2\Pi-I)}W.
\end{equation}
$P^{(SV)}(cV)$ transforms the singular value $c$ of $cV$ to $P(c)=1$. Namely $P^{(SV)}(cV)=V$, which means that Eq.~\eqref{eq:QSVT-circuit} is a quantum circuit for unitary $V$ by using the block encoding $W$ and $W^\dagger$.
{Since \(U_{\phi}\) is unitary and its clean top block \(V\) is itself unitary, no amplitude can leak from the clean-input subspace into its orthogonal complement. Consequently, 
\begin{equation}
    U_{\Phi}J=JV,
\end{equation}
and hence the entire circuit implements \(V\) on clean inputs.}

In the next lemma, \(\mathcal W\) is any \emph{exact} unitary, later instantiated as the exact Clifford+T circuit \(\widetilde W\).  The only approximation
hypothesis concerns its clean block \(A=J^\dagger\mathcal WJ\).

\begin{lemma}[Robust one-point oblivious amplification]
\label{lem:robust-amplification}
Let \(\mathcal W\) be a unitary, let \(J\) be an isometry, and put
\begin{equation}
  A=J^\dagger\mathcal WJ.
  \label{eq:robust-A-definition}
\end{equation}
Suppose \(V\) is unitary and
\begin{equation}
  \norm{A-cV}\le\delta,
  \qquad
  0<c\le1,
  \qquad
  \delta<c/2.
  \label{eq:robust-hypothesis}
\end{equation}
There is an oblivious-amplification unitary \(\mathcal A\), using
\(Q=\Theta(1/c)\) total calls, alternating between \(\mathcal W\) and
\(\mathcal W^\dagger\), and \(O(Q)\) signal phases, whose clean top block
\begin{equation}
  A_{\mathrm{amp}}:=J^\dagger\mathcal AJ
  \label{eq:Aamp-definition}
\end{equation}
satisfies
\begin{equation}
  \norm{A_{\mathrm{amp}}-V}=O(Q^2\delta).
  \label{eq:amplified-top-error}
\end{equation}
If \(Q^2\delta\) is at most a sufficiently small constant, then the full
clean input-isometry error is
\begin{equation}
  \norm{\mathcal AJ-JV}=O(Q\sqrt\delta).
  \label{eq:amplified-isometry-error}
\end{equation}
In particular, if \(\delta=0\), \(\mathcal A\) implements \(V\) exactly
and all signal ancillas return to zero.
\end{lemma}

\begin{proof}
Let \(P\) be the degree-\(Q\) response from
Lemma~\ref{lem:exact-response}.  Apply the alternating phase sequence in Eq.~\eqref{eq:QSVT-circuit} to the exact unitary \(\mathcal W\), using the same clean projector \(\Pi=JJ^\dagger\) on the input and output sides. 

Write a singular-value decomposition and polar decomposition of \(A\)
as
\begin{equation}
  A=U_A\Sigma R_A^\dagger=\Omega|A|,
  \label{eq:A-polar-SVD}
\end{equation}
where
\begin{equation}
    \Omega=U_AR_A^\dagger \qquad \text{and} \qquad
  |A|=R_A\Sigma R_A^\dagger.
\end{equation}
Every singular value of \(cV\) is \(c\). Therefore
Eq.~\eqref{eq:robust-hypothesis} gives the bounds of $A$'s singular values
\begin{equation}
  |\sigma_j(A)-c|\le\delta
  \label{eq:singular-values-near-c}
\end{equation}
for every \(j\).  Since \(\delta<c/2\), \(A\) is invertible and
\(\Omega\) is unitary.  Also, because \(cI\) is scalar,
\begin{equation}
  \norm{|A|-cI}
  =\max_j|\sigma_j(A)-c|
  \le\delta.
  \label{eq:absolute-perturbation}
\end{equation}

For an odd response polynomial $P$, QSVT gives
\begin{equation}
  A_{\mathrm{amp}}=P^{(\mathrm{SV})}(A)
   =U_AP(\Sigma)R_A^\dagger
   =\Omega P(|A|).
  \label{eq:qsvt-polar-form}
\end{equation}

Now we show the distance between $A_{\mathrm{amp}}$ and $V$.
{ First, \(A=\Omega|A|\) implies the exact identity
\begin{equation}
  c(I-\Omega^\dagger V)
  =(cI-|A|)+\Omega^\dagger(A-cV).
  \label{eq:polar-identity}
\end{equation}
Both terms on the right have norm at most \(\delta\), so
\begin{equation}
  \norm{\Omega-V}
  =\norm{I-\Omega^\dagger V}
  \le\frac{2\delta}{c}.
  \label{eq:polar-perturbation}
\end{equation}

Second, $|P(x)|\le 1$ for $x\in [-1,1]$ and Markov's inequality imply
\begin{equation}
  \max_{x\in[-1,1]}|P'(x)|\le Q^2,
  \label{eq:complex-markov}
\end{equation}
Then we have
{\begin{align}
  |P(\sigma_j(A))-P(c)|
  &=
  \left|\int_c^{\sigma_j(A)}P'(x)\,dx\right| \notag\\
  &\le
  \max_{t\in[-1,1]}|P'(t)|
  |\sigma_j(A)-c| \notag\\
  &\le Q^2\delta .
\end{align}}
According to \(P(c)=1\) and
Eq.~\eqref{eq:absolute-perturbation}, we have
\begin{align}
  \norm{P(|A|)-I}
   &=\max_j|P(\sigma_j(A))-P(c)|
    \le Q^2\delta.
  \label{eq:polynomial-perturbation}
\end{align}}

Combining Eqs.~\eqref{eq:qsvt-polar-form},
\eqref{eq:polar-perturbation}, and
\eqref{eq:polynomial-perturbation},
\begin{align}
  \norm{A_{\mathrm{amp}}-V}
   &\le\norm{\Omega(P(|A|)-I)}+\norm{\Omega-V}\notag\\
   &\le Q^2\delta+\frac{2\delta}{c}
    \le3Q^2\delta,
  \label{eq:top-error-expanded}
\end{align}
where the last inequality uses \(Q\ge1/c\) from
Eqs.~\eqref{eq:Q-explicit-bounds}.  This proves
Eqs.~\eqref{eq:amplified-top-error}.

It remains to control ancilla leakage.  Define
\begin{equation}
  E:=(I-JJ^\dagger)\mathcal AJ.
  \label{eq:leakage-operator}
\end{equation}
Then
\begin{equation}
  \mathcal AJ=JA_{\mathrm{amp}}+E,
  \label{eq:A-decomposition-clean-leakage}
\end{equation}
and the two terms on the right have orthogonal ranges.  Unitarity of
\(\mathcal A\) gives
\begin{align}
  E^\dagger E
   &=J^\dagger\mathcal A^\dagger(I-JJ^\dagger)\mathcal AJ\notag\\
   &=I-A_{\mathrm{amp}}^\dagger A_{\mathrm{amp}}.
  \label{eq:leakage-identity}
\end{align}
Put \(e=\norm{A_{\mathrm{amp}}-V}\).  Since \(A_{\mathrm{amp}}\) is a
compression of a unitary, \(\norm{A_{\mathrm{amp}}}\le1\).  Using
\(V^\dagger V=I\),
\begin{align}
  \norm E^2
   &=\norm{I-A_{\mathrm{amp}}^\dagger A_{\mathrm{amp}}}\notag\\
   &=\norm{V^\dagger(V-A_{\mathrm{amp}})
      +(V^\dagger-A_{\mathrm{amp}}^\dagger)A_{\mathrm{amp}}}\notag\\
   &\le e+e\norm{A_{\mathrm{amp}}}
    \le2e.
  \label{eq:leakage-from-top-error}
\end{align}
Finally,
\begin{align}
  \norm{\mathcal AJ-JV}
   &\le\norm{J(A_{\mathrm{amp}}-V)}+\norm E\notag\\
   &\le e+\sqrt{2e}
    =O(Q\sqrt\delta)
  \label{eq:clean-error-final-robust}
\end{align}
when \(Q^2\delta=O(1)\).  If \(\delta=0\), then \(e=0\) and
\(E=0\), proving exact logical action and exact ancilla return.
\end{proof}

\subsection{Clifford+$T$ circuit for the general unitary}
In this section, we show the $T$-count for the general unitary.

First we implement the signal rotation
\begin{equation}
 e^{\ii\phi(2\Pi-I)}.
  \label{eq:centered-signal-phase}
\end{equation}
in the QSVT circuit.

\begin{lemma}
\label{lem:signal-phase}
Suppose an alternating sequence contains \(M\) known signal rotations
\(e^{\ii\phi_1(2\Pi-I)},\ldots,e^{\ii\phi_M(2\Pi-I)}\).  They can be implemented total error at most $\eta$ using
\begin{equation}
  O\!\left(M[a+\log (M/\eta)]\right)
  \label{eq:signal-phase-cost}
\end{equation}
T gates and $O(a)$ ancillas.
\end{lemma}
\begin{proof}
    Recall that $\Pi=JJ^\dagger$ (Eq.\ref{eq:projector}). Ref.~\cite{Gilyen2019} shows that $e^{\ii\phi_M(2\Pi-I)}$ can be decomposed into two $O(a)$-qubit Toffoli gates and one Rz gate. The Toffoli gate can be implemented exactly using $O(a)$ $T$ gates and ancillas. And each Rz gate can be approximated using $O(\log(M/\eta))$ $T$ gates up to error $\eta/M$ by Lemma \ref{lem:Rz-Tcount}. Then the total error is $\eta$ and the total $T$-count is $O\!\left(M[a+\log (M/\eta)]\right)$.
\end{proof}

Now we show the $T$-count and ancilla-count for the general unitary.
\begin{theorem}[Restatement of Theorem \ref{thm:main}]
\label{thm:main-restate}
For every effectively specified \(U\in\U(d)\), there exists a
Clifford+\(T\) circuit that implements \(U\) with error at most
\(\eps\) in the sense of Definition~\ref{def:clean}.  If \(L\le d\), the circuit has \(T\)-count
\begin{equation}
  O\!\left(d^{5/4}L^{5/8}\log d\right)
\end{equation}
 and uses \(O(d\sqrt L)\) clean ancillas.  

\end{theorem}
\begin{proof}
  For any $U\in\U(d)$, by Lemma \ref{lem:flatten}, there exist two Boolean phase oracles $D_1,D_2$ such that
\begin{equation}
  U=D_1H_d\,V\,H_dD_2,
  \label{eq:undo-flattening}
\end{equation}
and $V$ satisfies Eq.~\eqref{eq:block-flat}.
The Walsh transforms are Clifford operations.  By
Lemma~\ref{lem:boolean-phase}, the two Boolean phase oracles can be implemented exactly using \(O(\sqrt d)\) \(T\) gates and ancillas in total. Now we implement the circuit for block-flattened unitary $V$.

We now apply Lemma~\ref{lem:robust-amplification} to the exact compiled unitary \(\mathcal W=\widetilde W\).  
According to Eq.~\eqref{eq:QSVT-circuit} and Lemma~\ref{lem:robust-amplification}, the quantum circuit consist of $O(Q)=O(\rho)$ signal rotations $e^{{\mathrm i}\phi_j(2\Pi-I)}$, $\widetilde W$ and $\widetilde W^\dagger$ in the quantum circuits for implementing $V$. 

Lemma~\ref{lem:compiled-base} already proved
\begin{equation}
  \norm{J^\dagger\widetilde WJ-cV}\le\delta.
  \label{eq:compiled-block-ready-for-amp}
\end{equation}
For any $\eps\in(0,1)$, choose
\begin{equation}
  \delta=\frac{\eps^2}{C\cdot Q^2}
  =\Theta\!\left(\frac{\eps^2}{\rho^2}\right)
  \label{eq:delta-choice}
\end{equation}
for some sufficiently large constant $C>0$. Then $Q^2\delta=\eps^2/C$ is at most a sufficiently small constant and $\delta=\eps^2/CQ^2\le \eps^2c^2/C<c/2$, which satisfies the condition in Lemma \ref{lem:robust-amplification}.
By Lemma \ref{lem:robust-amplification}, the $O(\rho)$ number of $\widetilde W$ and $\widetilde W^\dagger$ introduce a total error at most $\eps/2$ for implementing $V$. 

Define $L=n+\log(1/\epsilon)$ and
\begin{equation}
  S_0\defeq d\sqrt L+b^2L.
  \label{eq:S0-definition}
\end{equation}
Lemma~\ref{lem:compiled-base} and Eq.~\eqref{eq:delta-choice} show that one
query to \(\widetilde W\) or \(\widetilde W^\dagger\) costs 
 {\begin{align}
    &O\left(d\sqrt{k+\log(1/\delta)}+b^2(k+\log(1/\delta))\right)\notag\\
    =&O\left(d\sqrt{k+\log(1/\eps)+\log(Q)}+b^2(k+\log(1/\eps)+\log(Q))\right)\notag\\
    =&O(d\sqrt{L}+b^2L)\notag\\
    =&O(S_0)
\end{align}}
$T$ gates and ancillas.  Then total $T$-count and ancilla-count for  all \(\widetilde W\) and \(\widetilde W^\dagger\) are
\begin{equation}\label{eq:W}
    O(\rho S_0) \qquad \text{and}\qquad O(S_0).
\end{equation}

The signal rotations checks those workspace qubits together with \(\X,\f\), so the parameter
\(a\) in Lemma~\ref{lem:signal-phase} is \(O(S_0)\).  The quantum circuit Eq.~\eqref{eq:QSVT-circuit} contains \(M=O(Q)\) signal phases.  Moreover,
\(Q\le O(d)\) and \(\eta=\Theta(\eps)\), so
\begin{equation}
  \log (M/\eta)
  =O(n+ {\log(1/\eps)})=O(L).
  \label{eq:signal-log-is-L}
\end{equation}
 {The exact-phase amplified circuit has clean-input error at most \(\eps/2\) by Lemma~\ref{lem:robust-amplification}. Set \(\eta=\eps/2\). By Lemma~\ref{lem:signal-phase}, approximating the \(M\) signal rotations introduces error at most
\(\eps/2\).}
Lemma~\ref{lem:signal-phase} shows that when $L\le d$, the total $T$-count and ancilla-count for all signal rotations are
\begin{equation}
  O(\rho (S_0+L))=O(\rho S_0),
  \qquad \text{and} \qquad
  O(S_0).
  \label{eq:amplification-resources}
\end{equation}
Suppose first that \(L\le d\).  Lemma~\ref{lem:flatten} implies
\begin{equation}
  \rho=Dg
  \le C_{\mathrm{flat}}\sqrt{\frac{d}{b}}\log(2d)
  =O\!\left(\sqrt{\frac{d}{b}}\log d\right).
  \label{eq:rho-resource-bound}
\end{equation}
Combining Eqs.~\eqref{eq:S0-definition},
\eqref{eq:W} and \eqref{eq:amplification-resources}, and adding $T$-count of two Boolean phase oracles,
gives the $T$-count for general unitary $U$:
\begin{align}
  &O\!\left(\rho[d\sqrt L+b^2L]+\sqrt d\right)\notag\\
  =&O\!\left(
      \log d\left[
        d^{3/2}b^{-1/2}\sqrt L
        +d^{1/2}b^{3/2}L
      \right]
    \right).
  \label{eq:T-before-optimization}
\end{align}
And the ancilla-count is 
\begin{equation}
    O(S_0)=O(d\sqrt{L}+b^2L)
\end{equation}
Choose $b=\Theta(b_\star)$
\begin{equation}
  b_\star=d^{1/2}L^{-1/4}.
  \label{eq:b-star}
\end{equation}
For \(L\le d\), the $T$-count and ancilla-count for general unitary $U$ are
\begin{equation}
  O\!\left(d^{5/4}L^{5/8}\log d\right)\qquad\text{and}\qquad O(d\sqrt{L}).
  \label{eq:T-optimized}
\end{equation}
 This completes the proof.
\end{proof}
When \(L>d\), we instead use the circuit construction in
\cite[Theorem~1.1]{Tan2025}.  Its \(T\)-count satisfies
\begin{equation}
  O\!\left(d^{4/3}L^{2/3}+dL\right)=O(dL),
  \label{eq:tan-high-precision-count}
\end{equation}
and its ancilla count is
\(O(d^{2/3}L^{1/3}+L)=O(L)\). 

\section{Conclusion}
\label{sec:conclusion}

We have shown that an arbitrary effectively specified unitary
\(U\in\U(d)\) can be synthesized over Clifford+\(T\), in the regime
\(L\le d\), with \(T\)-count
\begin{equation}
  O\!\left(d^{5/4}L^{5/8}\log d\right).
\end{equation}
This bound is \(o(d^{4/3}L^{2/3})\) uniformly throughout
\(L\le d\), and therefore improves Tan's previous worst-case bound over
the entire regime.

The key idea is to treat the target unitary as a single block-encoded
object rather than decomposing it into a long product of simpler
unitaries.  Boolean sign diagonals and Walsh transforms simultaneously
flatten all blocks of the target.  Normalizing and dilating these blocks
then allows them to be organized into one jointly compiled \(\SELECT\),
whose block is proportional to the full unitary.  Quantum singular value transformation removes the resulting
normalization by mapping the common encoded singular value to one.  Balancing the
normalization overhead against the cost of compiling the selected
dilations yields the exponent \(5/4\).

The known lower bound at constant accuracy remains
\(\Omega(d)\)~\cite{GossetKothariWu2026}, leaving a multiplicative gap of
\(\widetilde O(d^{1/4})\).  Determining whether arbitrary unitaries can
be synthesized with \(\widetilde O(d)\) \(T\) gates, or establishing a
stronger lower bound, remains the central open problem.

