\section{{Proof of Lemma \ref{lem:exact-response}}}
\label{append:proof-restate}
{
Let $P\in\mathbb{C}[x]$ be a complex polynomial $p(x)=\sum_{j=0}^k a_jx^j$, then $p^*(x)\defeq \sum_{j=0}^k a^*_jx^j$ and $\operatorname{Re}p(x)\defeq \sum_{j=0}^k \operatorname{Re}(a_j)x^j$. If $d$ is odd (even), then polynomial $p$ has parity-$(d \mod 2)$ means $p$ is odd (even).
\begin{lemma}[\cite{Gilyen2019}]\label{lem:realpoly-to-complexpoly}
    Let $p_0(x)\in\mathbb{R}[x]$ be a degree-$Q$ polynomial for some $Q\ge 1$, such that $p_0(x)$ has parity-$(Q\mod 2)$ and $|p_0(x)|\le 1$ for all $x\in[-1,1]$. Then there exists a degree-$Q$ polynomial $P(x)\in\mathbb{C}[x]$ satisfying $\operatorname{Re} P=p_0$, and 
    \begin{enumerate}
        \item $P$ has parity-$(Q\mod 2)$,
        \item $\forall x\in[-1,1]$: $|P(x)|\le 1$,
        \item $\forall x\in (-\infty,-1]\cup [1,\infty)$: $|P(x)|\ge 1$,
        \item if $Q$ is even, then $\forall x\in\mathbb{R}$: $P(ix)P^*(ix)\ge 1$.
    \end{enumerate}
\end{lemma}

\begin{lemma}[Restatement of Lemma \ref{lem:exact-response}]
\label{lem:exact-response-restate}
For every \(0<c\le1\), there is an odd integer $Q=\Theta(1/c)$ and a degree-$Q$ polynomial $P(x)\in\mathbb{C}[x]$
such that $P(x)$ satisfies the four properties in Lemma \ref{lem:realpoly-to-complexpoly} and
\begin{equation}
  P(c)=1.
\end{equation}

\end{lemma}
\begin{proof}
Let \(Q\) be the smallest positive odd integer satisfying
\begin{equation}
  \sin\!\left(\frac{\pi}{2Q}\right)\le c.
  \label{eq:Q-choice}
\end{equation}
Using $2x/\pi \le \sin x \le x$ for $x\in [0,\pi/2]$, together with the minimality of $Q$, we obtain
\begin{equation}
  \frac1c\le Q\le\frac{\pi}{2c}+2.
  \label{eq:Q-explicit-bounds}
\end{equation}
Hence \(Q=\Theta(1/c)\).

Set $\beta\defeq\sin(\pi/(2Q))/c\le1$
and write $Q=2m+1$. Define a real polynomial
\begin{equation}
  p_0(x)\defeq\sin\!\bigl(Q\arcsin(\beta x)\bigr)=(-1)^mT_Q(\beta x),
  \label{eq:p0-definition}
\end{equation}
where $T_Q$ is the degree-$Q$ Chebyshev polynomial of the first kind. Therefore, $p_0$ has parity-$(Q\mod 2)$
Moreover, for every $x\in[-1,1]$, we have $\beta x\in[-1,1]$. Then
\begin{equation}
  |p_0(x)|\le1.
  \label{eq:p0-bounded}
\end{equation}
At the distinguished point,
\begin{align}
  p_0(c)
   &=\sin\!\left(
      Q\arcsin\!\left(\sin\frac{\pi}{2Q}\right)
     \right)
    =1.
  \label{eq:p0-at-c}
\end{align}
According to Lemma \ref{lem:realpoly-to-complexpoly}, there exists a degree-$Q$ polynomial $P(x)\in\mathbb{C}[x]$, such that $P$ satisfies the four conditions in Lemma \ref{lem:realpoly-to-complexpoly} and
\begin{equation}
  \operatorname{Re}P(x)=p_0(x).
  \label{eq:qsp-completion-real-part}
\end{equation}
Since \(\operatorname{Re}P(c)=p_0(c)=1\) and
\(|P(c)|\le1\), we have
\begin{equation}
  P(c)=1.
  \label{eq:P-at-c-exact}
\end{equation}
\end{proof}
