\section{Synthesis of multiplexed unitaries}
\label{sec:multiplexed}

This appendix applies the block-flattening construction to a family of
unitaries selected by a quantum address.  The additional ingredient is
that a single pair of Boolean sign diagonals can flatten every member of
the family simultaneously.

Let \(M=2^m\ge2\), \(K=2^k\ge2\), and \(0<\eps<1/2\).  For a
classically specified family \(\{U_x\}_{x=0}^{M-1}\), consider the
multiplexed unitary
\begin{equation}
  \mathcal U
  :=\sum_{x=0}^{M-1}\proj{x}_A\otimes U_x,
  \qquad U_x\in\U(K).
  \label{eq:mux-definition}
\end{equation}
Throughout this appendix, set
\begin{equation}
  R:=\log(2MK),
  \qquad
  \Lambda:=1+\log K+\log(1/\eps).
  \label{eq:mux-parameters}
\end{equation}
A direct application of Lemma~\ref{lem:tan-controlled} to
\(\mathcal U\) gives the benchmark
\begin{equation}
  T_{\mathrm{direct}}
  =O\!\left(
    \sqrt M\,K\sqrt\Lambda+K^2\Lambda
  \right).
  \label{eq:direct-mux-Tan}
\end{equation}
We next reduce the quadratic target-side term by applying the block
construction jointly to the entire family.

\subsection{Simultaneous flattening}

Choose a power of two \(h\mid K\), and set \(D=K/h\).  Partition each
\(U_x\) into \(D\times D\) blocks of size \(h\times h\).  Let
\(Q_I:\C^K\to\C^h\) denote the corresponding block selector,
\begin{equation}
  Q_I\ket{J,y}=\delta_{IJ}\ket y,
  \qquad 0\le I,J<D.
  \label{eq:mux-block-selector}
\end{equation}
We write \(H_K=H^{\otimes k}\).

\begin{lemma}[Common-sign flattening]
\label{lem:mux-common-flatten}
There exist Boolean sign diagonals \(S_1,S_2\in\U(K)\), independent of
\(x\), such that the unitary
\begin{equation}
  V_x=H_KS_1U_xS_2H_K
  \label{eq:mux-flattened-branch}
\end{equation}
satisfies
\begin{equation}
  \norm{Q_IV_xQ_J^\dagger}
  \le
  g_{\mathrm{mux}}
  :=\min\!\left\{
    1,
    C_{\mathrm{flat}}\sqrt{\frac hK}\,R
  \right\}
  \label{eq:mux-g}
\end{equation}
for every \(x,I,J\), where \(C_{\mathrm{flat}}=16\ln2\).
\end{lemma}

\begin{proof}
Choose \(S_2=\operatorname{diag}(\xi_1,\ldots,\xi_K)\), where the
\(\xi_\ell\) are independent Rademacher random variables.  For fixed
\(x,p,q\), the entry \((U_xS_2H_K)_{pq}\) is a complex Rademacher sum
whose squared coefficient norm is \(1/K\).  Set
\(\alpha=4\sqrt{\ln(2MK)/K}\).  Applying
Eq.~\eqref{eq:complex-entry-tail} and taking a union bound over all
\(MK^2\) entries gives
\begin{align}
  &\Pr\!\left\{
    \max_{x,p,q}|(U_xS_2H_K)_{pq}|\ge\alpha
  \right\}
  \notag\\[-1mm]
  &\hspace{2cm}\le4MK^2(2MK)^{-4}<1.
  \label{eq:mux-entry-union-bound}
\end{align}
Fix a choice of \(S_2\) for which this event does not occur.

For each \(x,J\), define the \(K\times h\) isometry
\begin{equation}
  Z_{x,J}:=U_xS_2H_KQ_J^\dagger,
  \label{eq:mux-Z}
\end{equation}
and write its \(\ell\)-th row as \(z_{x,J,\ell}^\dagger\).  The entry
bound above implies
\begin{equation}
  \norm{z_{x,J,\ell}}^2
  \le16\frac hK\ln(2MK)
  =:\mu_{\mathrm{mux}}.
  \label{eq:mux-row-coherence}
\end{equation}

Now choose \(S_1=\operatorname{diag}(\eta_1,\ldots,\eta_K)\) at random
and set \(a_{I,\ell}:=Q_IH_Ke_\ell\).  For fixed \(x,I,J\),
\begin{equation}
  Q_IH_KS_1Z_{x,J}
  =\sum_{\ell=1}^K
    \eta_\ell a_{I,\ell}z_{x,J,\ell}^\dagger.
  \label{eq:mux-matrix-series}
\end{equation}
The two variance matrices of this Rademacher series satisfy
\begin{align}
  \sum_\ell
    \norm{z_{x,J,\ell}}^2
    a_{I,\ell}a_{I,\ell}^\dagger
    &\preceq\mu_{\mathrm{mux}}I_h,
    \label{eq:mux-left-variance}\\
  \sum_\ell
    \norm{a_{I,\ell}}^2
    z_{x,J,\ell}z_{x,J,\ell}^\dagger
    &=\frac hK I_h.
    \label{eq:mux-right-variance}
\end{align}
Lemma~\ref{lem:rademacher}, with
\(t=16\sqrt{h/K}\ln(2MK)\), followed by a union bound over the
\(MD^2\) triples \(x,I,J\), gives a total failure probability at most
\begin{equation}
  2hMD^2(2MK)^{-8}<1.
  \label{eq:mux-block-union-bound}
\end{equation}
Thus one choice of \(S_1\) satisfies
\[
  \norm{Q_IV_xQ_J^\dagger}
  \le16\sqrt{\frac hK}\ln(2MK)
  =C_{\mathrm{flat}}\sqrt{\frac hK}\,R
\]
simultaneously for all \(x,I,J\).  Combining this with the trivial
unitary-subblock bound \(\norm{Q_IV_xQ_J^\dagger}\le1\) proves the
lemma.
\end{proof}

Define
\begin{equation}
  \mathcal V:=\sum_{x=0}^{M-1}\proj{x}_A\otimes V_x.
  \label{eq:mux-V}
\end{equation}
Since the signs in Lemma~\ref{lem:mux-common-flatten} are common to all
branches,
\begin{equation}
  \mathcal U
  =(I_A\otimes S_1H_K)\,
    \mathcal V\,
    (I_A\otimes H_KS_2).
  \label{eq:mux-unflatten}
\end{equation}
The two sign diagonals are implemented exactly using \(O(\sqrt K)\)
\(T\) gates and clean ancillas in total, and they occur only once,
outside the amplification sequence.

\subsection{Block encoding and synthesis}

Split the target register into a \(D\)-dimensional block label \(B\)
and an \(h\)-dimensional register \(Y\).  Introduce a
\(D\)-dimensional register \(X\) and a one-qubit flag \(f\), and define
\begin{equation}
  C_{x,IJ}:=\frac{Q_IV_xQ_J^\dagger}{g_{\mathrm{mux}}}.
  \label{eq:mux-C}
\end{equation}
Every \(C_{x,IJ}\) is a contraction.  Using the Julia--Halmos dilation
from Eq.~\eqref{eq:halmos-dilation}, define
\begin{multline}
  \SELECT_{\mathrm{mux}}
  :=\sum_{x=0}^{M-1}\sum_{I,J=0}^{D-1}
    \proj{x}_A\otimes\proj{I}_X\otimes\proj{J}_B\\
    {}\otimes\operatorname{Hal}(C_{x,IJ})_{fY}.
  \label{eq:mux-select}
\end{multline}
Let \(W_{\mathrm{mux}}\) apply \(H_D\) to \(X\), followed by
\(\SELECT_{\mathrm{mux}}\), \(H_D\) on \(B\), and a swap of \(X\) and
\(B\).  Let \(J_{0,\mathrm{mux}}\) append \(X=0\) and \(f=0\), while
leaving \(A,B,Y\) as logical registers.  The basis-state calculation
of Lemma~\ref{lem:uniform-block} gives
\begin{equation}
  J_{0,\mathrm{mux}}^\dagger
  W_{\mathrm{mux}}J_{0,\mathrm{mux}}
  =\frac{\mathcal V}{\rho_h},
  \label{eq:mux-clean-block}
\end{equation}
where
\begin{equation}
  \rho_h:=Dg_{\mathrm{mux}}
  =\min\!\left\{
    D,C_{\mathrm{flat}}\sqrt D\,R
  \right\}.
  \label{eq:mux-rho}
\end{equation}
The normalization is independent of \(x\), and the address register is
not included in the signal projector.  Hence the same amplification
sequence applies to arbitrary superpositions of addresses.

The SELECT in Eq.~\eqref{eq:mux-select} acts on
\(N=m+2\log D+\log h+1\) input qubits, of which
\(q=\log h+1\) are target qubits.  Consequently,
\begin{equation}
  2^{(N+q)/2}=2\sqrt M\,K,
  \qquad
  4^q=4h^2.
  \label{eq:mux-compiler-factors}
\end{equation}
Define
\begin{equation}
  S_h:=\sqrt M\,K\sqrt\Lambda+h^2\Lambda.
  \label{eq:mux-Sh}
\end{equation}

\begin{theorem}[Parameterized multiplexed-unitary synthesis]
\label{thm:mux-parameterized}
