\begin{equation}
  T_{\mathrm{mux}}
  =O\!\left(\rho_hS_h+\sqrt K\right),
  \label{eq:mux-parameterized-bound}
\end{equation}
and \(O(S_h+\sqrt K+\log K)\) clean ancillas.
\end{theorem}

\begin{proof}
Fix a sufficiently small constant \(c_0>0\), and compile
\(W_{\mathrm{mux}}\) to a Clifford+\(T\) unitary with error
